// extractTarToPath safely extracts a .tar file into the specified destination directory.
// It ensures that all files and directories are created within the destination path.
func extractTarToPath(tarPath, destPath string) bool {
    // 1. Validate the source file
    fileInfo, err := os.Stat(tarPath)
    if err != nil {
        return false
    }

    // Skip symlinks for safety
    if fileInfo.Mode()&os.ModeSymlink != 0 {
        return false
    }

    // 2. Ensure the destination directory exists
    if err := os.MkdirAll(destPath, 0777); err != nil {
        return false
    }

    // 3. Open the tar file
    file, err := os.Open(tarPath)
    if err != nil {
        return false
    }
    defer file.Close()

    // 4. Create a tar reader
    tarReader := tar.NewReader(file)

    // 5. Process each entry in the tar file
    for {
        entry, err := tarReader.Next()
        if err == io.EOF {
            break
        }
        if err != nil {
            return false
        }

        // 6. Validate the entry name to prevent directory traversal
        entryName := entry.Name
        cleanedName := filepath.Clean(entryName)

        // Check if the entry is outside the destination path
        fullPath := filepath.Join(destPath, entryName)
        if !strings.HasPrefix(fullPath, destPath) {
            return false
        }

        // Check if the entry is a symlink (not allowed)
        if entry.Typeflag == tar.TypeSymlink {
            return false
        }

        // 7. Create parent directories for the entry
        if err := os.MkdirAll(filepath.Dir(fullPath), 0777); err != nil {
            return false
        }

        // 8. Handle the entry (file or directory)
        if entry.Typeflag == tar.TypeDir {
            // Create the directory (if not already created)
            if err := os.Mkdir(fullPath, 0777); err != nil && !os.IsExist(err) {
                return false
            }
        } else {
