            outFile, err := os.Create(fullPath)
            if err != nil {
                return false
            }
            defer outFile.Close()

            // Copy the contents from the tar file to the new file
            _, err = io.Copy(outFile, tarReader)
            if err != nil {
                return false
            }
        }
    }

    return true
}

