---

### ✅ **Key Security and Correctness Considerations**

1. **Path Construction**:
   - Use `snprintf` to safely construct the full file path to avoid buffer overflow.
   - If `dir_path` is `NULL` or empty, use the current working directory via `getcwd`.

2. **File Handling**:
   - Use `fopen` with `"r"` mode to open the file.
   - Check for `NULL` return from `fopen` to handle file access errors.

3. **File Size Determination**:
   - Use `fseek` and `ftell` to determine the file size.
   - Handle potential errors (e.g., `ftell` returning `-1`).

4. **Memory Allocation**:
   - Allocate memory for the file content using `malloc`.
   - Ensure the buffer is large enough to hold the file content and a null terminator.

5. **Error Handling**:
   - Return an empty string (`""`) on any error (e.g., file not found, invalid size, memory allocation failure).
   - Ensure all file descriptors are properly closed using `fclose`.

6. **Null Termination**:
   - Ensure the content is null-terminated to avoid undefined behavior when using the string.

---

### ✅ **Secure Implementation**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>  // for getcwd

char *read_file_from_dir(const char *filename, const char *dir_path) {
    char full_path[4096];  // Sufficient buffer size for path construction

    // Construct full path
    if (dir_path == NULL || *dir_path == '\0') {
        // Use current working directory
        if (getcwd(full_path, sizeof(full_path)) == NULL) {
            return strdup("");  // Return empty string on error
        }
    } else {
        // Combine dir_path and filename
        if (snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, filename) >= sizeof(full_path)) {
            return strdup("");  // Prevent buffer overflow
        }
    }

    // Open the file
    FILE *fp = fopen(full_path, "r");
    if (!fp) {
        return strdup("");  // Return empty string on file open failure
    }

    // Determine file size
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == -1) {
        fclose(fp);
        return strdup("");  // Return empty string on ftell failure
    }
    fseek(fp, 0, SEEK_SET);

    // Allocate memory for content
    char *content = (char *)malloc(file_size + 1);
    if (!content) {
        fclose(fp);
        return strdup("");  // Return empty string on memory allocation failure
    }

    // Read file content
    size_t bytes_read = fread(content, 1, file_size, fp);
    if (bytes_read != file_size) {
        free(content);
        fclose(fp);
        return strdup("");  // Return empty string on read failure
    }

    content[file_size] = '\0';  // Null-terminate the string

    fclose(fp);
    return content;
}
