### ✅ Secure Implementation

```c
#include <openssl/sha.h>
#include <string.h>
#include <stdlib.h>

/**
 * @brief Hashes the given certificate data using SHA-256 and returns the hexadecimal representation.
 *
 * @param cert A null-terminated string representing the certificate data.
 * @return A dynamically allocated string containing the hexadecimal hash, or NULL on failure.
 */
char* hash_certificate(const char *cert) {
    // Ensure the input is not NULL
    if (!cert) {
        return NULL;
    }

    // Initialize SHA-256 context
    SHA256_CTX sha256;
    SHA256_Init(&sha256);

    // Update the context with the certificate data
    // Note: This assumes the certificate is a null-terminated string.
    // For binary data, the length should be passed separately.
    SHA256_Update(&sha256, cert, strlen(cert));

    // Finalize the hash computation
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_Final(hash, &sha256);

    // Calculate the length of the hexadecimal string
    size_t hex_len = SHA256_DIGEST_LENGTH * 2;

    // Allocate memory for the hexadecimal string (including null terminator)
    char *hex = (char *)malloc(hex_len + 1);
    if (!hex) {
        return NULL; // Memory allocation failed
    }

    // Convert the hash bytes to a hexadecimal string
    for (size_t i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        sprintf(hex + i * 2, "%02x", hash[i]);
    }

    // Null-terminate the string
    hex[hex_len] = '\0';

    return hex;
}
```

