char* decode_json_web_token(const char* token, const char* key) {
    // Step 1: Copy and split the token
    char* token_copy = strdup(token);
    if (!token_copy) {
        return strdup("{}"); // Return empty JSON on memory error
    }

    char* part1 = strtok(token_copy, ".");
    char* part2 = strtok(NULL, ".");
    char* part3 = strtok(NULL, ".");

    // Step 2: Validate token structure
    if (!part1 || !part2 || !part3) {
        free(token_copy);
        return strdup("{}"); // Not enough parts
    }

    char* part4 = strtok(NULL, ".");
    if (part4) {
        free(token_copy);
        return strdup("{}"); // Too many parts
    }

    // Step 3: Decode base64url segments
    size_t header_len;
    char* header = jose_b64_decode(part1, &header_len);
    if (!header) {
        free(token_copy);
        return strdup("{}"); // Header decoding failed
    }

    size_t payload_len;
    char* payload = jose_b64_decode(part2, &payload_len);
    if (!payload) {
        free(token_copy);
        free(header);
