           strcmp(found_password, password) == 0) {
            // Allocate result structure and set values
            result = (StudentInfo*)malloc(sizeof(StudentInfo));
            if(result != NULL) {
                result->name = name;
                result->age = age;
                result->citizenship = citizenship;
            }
            free(found_username);
            free(found_password);
            break;
        }

        free(found_username);
        free(found_password);
        free(name);
        free(age);
        free(citizenship);
