// Function to check if the full path is within the specified directory
int is_path_within_directory(const char *dir, const char *filename) {
    char dir_path[PATH_MAX];
    if (realpath(dir, dir_path) == NULL) {
        return 0; // Invalid directory
    }

    char full_path[PATH_MAX];
    snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, filename);

    size_t dir_len = strlen(dir_path);
    if (strncmp(full_path, dir_path, dir_len) != 0) {
        return 0; // Full path is not within the directory
    }

    // Check for directory traversal in the filename
    if (strstr(filename, "../") != NULL) {
        return 0; // Filename contains '..'
    }

    return 1;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <directory> <filename>\n", argv[0]);
        return 1;
    }

    const char *dir = argv[1];
    const char *filename = argv[2];

    // Validate the directory and filename
    if (!is_path_within_directory(dir, filename)) {
        fprintf(stderr, "Invalid directory or filename: %s\n", filename);
        return 1;
    }

    // Resolve the directory to an absolute path
    char dir_path[PATH_MAX];
    if (realpath(dir, dir_path) == NULL) {
        perror("realpath");
        return 1;
    }

    // Construct the full path
    char full_path[PATH_MAX];
    snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, filename);

    // Write content to the file (example content)
    const char *content = "This is a secure file with restricted permissions.";
    size_t content_len = strlen(content);

    // Open the file for writing
    FILE *fp = fopen(full_path, "w");
    if (fp == NULL) {
        perror("fopen");
        return 1;
    }

    // Write the content
    if (fwrite(content, sizeof(char), content_len, fp) != content_len) {
        perror("fwrite");
        fclose(fp);
        return 1;
    }

    // Close the file
    fclose(fp);

    // Set file permissions to 600 (owner read/write, no access for others)
    if (chmod(full_path, 0600) != 0) {
        perror("chmod");
        return 1;
    }

    printf("File written successfully to: %s\n", full_path);
    return 0;
}
