    // Check if the directory exists and is a directory, not a symlink
    struct stat st;
    if (fstatat(AT_FDCWD, dir_path.c_str(), &st, AT_SYMLINK_NOFOLLOW) == -1) {
        return "";
    }

    if (!S_ISDIR(st.st_mode)) {
        return "";
    }

    // Check if the user has read and execute permissions on the directory
    if (!(st.st_mode & (S_IRUSR | S_IXUSR))) {
        return "";
    }

    // Save original CWD
    char original_cwd[PATH_MAX];
    if (getcwd(original_cwd, sizeof(original_cwd)) == nullptr) {
        return "";
    }

    // Change to the directory
    if (chdir(dir_path.c_str()) != 0) {
        return "";
    }

    // Execute ls -l and capture output
    FILE *fp = popen("ls -l", "r");
    if (!fp) {
        chdir(original_cwd);
        return "";
    }

    char buffer[1024];
    std::string result;
    while (fgets(buffer, sizeof(buffer), fp)) {
        result += buffer;
    }
    pclose(fp);

    // Restore original CWD
    if (chdir(original_cwd) != 0) {
        return "";
    }

    return result;
}
