#include <cstdio>
#include <cstdlib>
#include <string>

std::string create_private_key() {
    // Command to generate an RSA private key with 2048 bits
    const char* command = "openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 2>/dev/null";

    // Open a pipe to the command
