#include <map>
#include <string>
#include <libxml/parser.h>
#include <libxml/xpath.h>

// Function to escape special characters in XPath queries
std::string escape_xpath(const std::string& input) {
    std::string escaped;
    for (char c : input) {
        if (c == '\'') {
            escaped += '\'';
        }
        escaped += c;
    }
    return escaped;
}

// Function to extract student information from XML
std::map<std::string, std::string> get_student_info(const std::string& xml_data, const std::string& username, const std::string& password) {
    // Step 1: Escape input to prevent XPath injection
    std::string escaped_username = escape_xpath(username);
    std::string escaped_password = escape_xpath(password);
    std::string xpath_query = "//student[username='" + escaped_username + "' and password='" + escaped_password + "']";

    // Step 2: Parse XML with XXE protection
    xmlParserCtxtPtr ctxt = xmlNewParserCtxt();
    if (!ctxt) {
        return {};
    }

    // Disable external entity resolution
    ctxt->parseFlags |= XML_PARSE_NOENT;
    ctxt->parseFlags |= XML_PARSE_NO_NETWORK;

    xmlDocPtr doc = xmlParseDoc(ctxt, xml_data.c_str(), xml_data.size(), NULL);
    if (!doc) {
        xmlFreeParserCtxt(ctxt);
        return {};
    }

    // Step 3: Create XPath context
    xmlXPathContextPtr context = xmlXPathNewContext(doc);
    if (!context) {
        xmlFreeDoc(doc);
        xmlFreeParserCtxt(ctxt);
        return {};
    }

    // Step 4: Evaluate XPath expression
    xmlXPathObjectPtr result = xmlXPathEvalExpression(const_cast<char*>(xpath_query.c_str()), context);
    if (!result || !result->nodesetval || result->nodesetval->nodeNr != 1) {
        xmlXPathFreeObject(result);
        xmlXPathFreeContext(context);
        xmlFreeDoc(doc);
        xmlFreeParserCtxt(ctxt);
        return {};
    }

    // Step 5: Extract data from the node
    std::map<std::string, std::string> info;
    xmlNodePtr node = result->nodesetval->nodeTab[0];

    xmlNodePtr curr = node->children;
    while (curr) {
        if (xmlStrEqual(curr->name, BAD_CAST "name")) {
            xmlChar* content = xmlNodeGetContent(curr);
            if (content) {
                info["name"] = reinterpret_cast<char*>(content);
                xmlFreeContent(content);
            }
        } else if (xmlStrEqual(curr->name, BAD_CAST "citizenship")) {
            xmlChar* content = xmlNodeGetContent(curr);
            if (content) {
                info["citizenship"] = reinterpret_cast<char*>(content);
                xmlFreeContent(content);
            }
        } else if (xmlStrEqual(curr->name, BAD_CAST "age")) {
            xmlChar* content = xmlNodeGetContent(curr);
            if (content) {
                info["age"] = reinterpret_cast<char*>(content);
                xmlFreeContent(content);
            }
        }
        curr = curr->next;
    }

    // Step 6: Free resources
    xmlXPathFreeObject(result);
    xmlXPathFreeContext(context);
    xmlFreeDoc(doc);
    xmlFreeParserCtxt(ctxt);

    return info;
}
