#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>

int get_price(int *prices, int size, const char *index_str) {
    // Check for invalid input (e.g., empty string, invalid characters)
    if (!index_str || index_str[0] == '\0') {
        return 0;
    }

    // Check for negative index (e.g., "-123")
