### ✅ Secure Implementation of `my_strdup`

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* my_strdup(const char* str) {
    if (str == NULL) {
        return NULL;  // Handle NULL input explicitly
    }

    size_t len = strlen(str);

    // Check for integer overflow when adding 1 for the null terminator
    if (len == (size_t)-1) {
        return NULL;  // Prevent overflow in allocation
    }

    char* dup = malloc(len + 1);

    if (dup == NULL) {
        return NULL;  // Handle allocation failure
    }

    // Use strncpy to safely copy the string and ensure null-termination
    strncpy(dup, str, len + 1);

    return dup;
}
