using namespace std;

// Function to calculate the Euclidean distance between two points
double distance(int x1, int y1, int x2, int y2) {
    return sqrt(pow(x2 - x1, 2) + pow(y2 - y1, 2));
}

// Function to find the closest pair of points using divide and conquer
pair<int, int> closestPair(vector<pair<int, int>>& points) {
    // Base case: if there are 2 or fewer points, compute the distance directly
    if (points.size() <= 3) {
        double minDist = numeric_limits<double>::max();
        pair<int, int> closest = { -1, -1 };
        for (int i = 0; i < points.size(); ++i) {
            for (int j = i + 1; j < points.size(); ++j) {
                double d = distance(points[i].first, points[i].second, points[j].first, points[j].second);
                if (d < minDist) {
                    minDist = d;
                    closest = { i, j };
                }
            }
        }
        return closest;
    }

    // Divide the points into left and right halves
    int mid = points.size() / 2;
    vector<pair<int, int>> leftPoints(points.begin(), points.begin() + mid);
    vector<pair<int, int>> rightPoints(points.begin() + mid, points.end());

    // Recursively find the closest pair in each half
    pair<int, int> leftClosest = closestPair(leftPoints);
    pair<int, int> rightClosest = closestPair(rightPoints);

    // Find the minimum distance between the two halves
    double d = min(distance(points[leftClosest.first].first, points[leftClosest.first].second, points[leftClosest.second].first, points[leftClosest.second].second),
                   distance(points[rightClosest.first].first, points[rightClosest.first].second, points[rightClosest.second].first, points[rightClosest.second].second));

    // Find the closest pair that crosses the vertical line dividing the two halves
    vector<pair<int, int>> strip;
    for (const auto& point : points) {
        if (abs(point.first - points[mid].first) < d) {
            strip.push_back(point);
        }
    }

    // Sort the strip by y-coordinate
    sort(strip.begin(), strip.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        return a.second < b.second;
    });

    // Check for closest pairs in the strip
    pair<int, int> stripClosest = { -1, -1 };
    for (int i = 0; i < strip.size(); ++i) {
        for (int j = i + 1; j < i + 7 && j < strip.size(); ++j) {
            double dStrip = distance(strip[i].first, strip[i].second, strip[j].first, strip[j].second);
            if (dStrip < d) {
                d = dStrip;
                stripClosest = { i, j };
            }
        }
    }

    // Return the closest pair between the left, right, and strip
    if (d == distance(points[leftClosest.first].first, points[leftClosest.first].second, points[leftClosest.second].first, points[leftClosest.second].second)) {
        return leftClosest;
    } else if (d == distance(points[rightClosest.first].first, points[rightClosest.first].second, points[rightClosest.second].first, points[rightClosest.second].second)) {
        return rightClosest;
    } else {
        return stripClosest;
    }
}

